form.find:
if ($editing) {
    // Edit form: hidden id input, native title input, submit button. The form submits
    // to the parent board's 'edit' action via the installed client's act() and
    // Object.fromEntries(new FormData($event.target)).
    $formAttrs = Html::attrs([
        'id' => $formId,
        'x-on:submit.prevent' => "act('edit', Object.fromEntries(new FormData(\$event.target)))",
    ]);
    $hiddenId = '<input type="hidden" name="id" value="' . $idEsc . '"/>';
    $submit = '<button type="submit" class="todo-save">' . $text['save'] . '</button>';
    $body = '<form ' . $formAttrs . '>' . $hiddenId . $input->output . $submit . '</form>';
} else {
    $editBtn = '<button type="button" class="todo-edit" aria-label="' . $text['edit'] . ': ' . $titleEsc . '"'
        . ' x-on:click="act(\'edit\', {id: \'' . $idEsc . '\'})"'
        . '>' . $text['edit'] . '</button>';
    $titleEl = '<span class="todo-title" ' . ($done ? '' : '') . 'title="">' . $titleEsc . '</span>';
    $body = $titleEl . $editBtn;
}

